import React, { useState } from 'react';
import styled from 'styled-components';
import FadeIn from './FadeIn';

const ProjectsContainer = styled.section`
  padding: 7rem 10vw;
  background: var(--surface);

  @media (max-width: 768px) {
    padding: 5rem 6vw;
  }
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
`;

const Card = styled.div`
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  transition: border-color 0.25s, transform 0.25s, box-shadow 0.25s;
  cursor: default;

  &:hover {
    border-color: rgba(232, 197, 71, 0.3);
    transform: translateY(-4px);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.4);
  }
`;

const Badge = styled.span`
  display: inline-block;
  font-size: 0.62rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  border: 1px solid rgba(232, 197, 71, 0.3);
  padding: 0.2rem 0.65rem;
  border-radius: 2px;
  margin-bottom: 1rem;
  width: fit-content;
`;

const CardTitle = styled.h3`
  font-family: var(--font-display);
  font-size: 1.2rem;
  margin-bottom: 0.75rem;
  line-height: 1.3;
`;

const CardDesc = styled.ul`
  list-style: none;
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.85;
  flex: 1;
  margin-bottom: 1.25rem;

  li {
    padding-left: 1rem;
    position: relative;
    margin-bottom: 0.35rem;

    &::before {
      content: '·';
      position: absolute;
      left: 0;
      color: var(--accent);
      font-size: 1.1rem;
      line-height: 1.5;
    }
  }
`;

const TechRow = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
`;

const TechPill = styled.span`
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--surface2);
  color: var(--muted);
  padding: 0.25rem 0.65rem;
  border-radius: 100px;
`;

const CardLink = styled.a`
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent2);
  text-decoration: none;
  margin-top: 1.25rem;
  transition: gap 0.2s;

  &:hover {
    gap: 0.8rem;
  }
`;

const projects = [
  {
    badge: 'Full Stack · MERN',
    name: 'Resume Enhancer Platform',
    desc: [
      'Full-stack MERN app that analyzes resumes and improves alignment with job descriptions.',
      'Built RESTful APIs with Express.js & Node.js to process resume content and JD inputs.',
      'Resume–JD matching logic to highlight skill gaps and missing keywords.',
      'MongoDB for storing resumes, JDs, enhancement results, and user submissions.',
    ],
    tech: ['MongoDB', 'Express.js', 'Node.js', 'JavaScript', 'GitHub'],
    link: null,
  },
  {
    badge: 'Full Stack · New',
    name: 'Job Tracker App',
    desc: [
      'Centralized dashboard to track job applications across stages — Applied, Interview, Offer, Rejected.',
      'React + TypeScript frontend with Node.js/Express backend and MongoDB storage.',
      'Filter, sort, and search capabilities with a clean kanban-style board view.',
      'Track company, role, applied date, notes, and status in one place.',
    ],
    tech: ['React', 'TypeScript', 'Node.js', 'MongoDB', 'Express.js'],
    link: null,
  },
  {
    badge: 'University Events · New',
    name: 'Uni Events Platform',
    desc: [
      'Full-stack web app for discovering, RSVPing, and managing university campus events.',
      'Student-facing React dashboard with event listings, filters by category and date.',
      'Admin panel for organizers to create, edit, and track real-time attendance.',
      'Seat availability counter and calendar-style event browsing UI.',
    ],
    tech: ['React', 'TypeScript', 'Node.js', 'MongoDB', 'CSS3'],
    link: null,
  },
  {
    badge: 'Portfolio · New',
    name: 'This Portfolio',
    desc: [
      'Designed and built entirely from scratch with a minimal, dark, typographic aesthetic.',
      'React.js SPA with smooth scroll navigation, IntersectionObserver fade-in animations.',
      'Fully component-based architecture mirroring production-grade project structure.',
      'Responsive across all screen sizes with styled-components for scoped styling.',
    ],
    tech: ['React', 'JavaScript', 'styled-components', 'HTML5', 'CSS3'],
    link: null,
  },
  {
    badge: 'UX Research',
    name: 'DoorDash Usability Study',
    desc: [
      'Conducted structured user interviews to map real-world usage patterns and pain points.',
      'Identified usability issues reported by ~60–70% of participants in navigation and checkout.',
      'Analyzed interview insights alongside user flows to uncover improvement opportunities.',
      'Proposed UX fixes — simplified CTAs, reduced checkout steps — targeting ~20–25% better task completion.',
    ],
    tech: ['UX Research', 'Figma', 'Usability Testing', 'Interview Methods'],
    link: null,
  },
  {
    badge: 'Web Development',
    name: 'Restaurant Website',
    desc: [
      'Responsive React.js restaurant site with reusable components for Home, Menu, About, Contact.',
      'Interactive navigation and dynamic content rendering using JavaScript.',
      'Modern CSS layout techniques for cross-device compatibility.',
      'Component-based architecture with clean, maintainable code practices.',
    ],
    tech: ['React.js', 'HTML5', 'CSS3', 'JavaScript'],
    link: null,
  },
];

const ProjectsSection = () => {
  return (
    <ProjectsContainer id="projects">
      <FadeIn>
        <p className="section-label">Projects</p>
        <h2 className="section-title">Things I've built</h2>
      </FadeIn>

      <Grid>
        {projects.map((project, i) => (
          <FadeIn key={i} delay={i * 80}>
            <Card>
              <Badge>{project.badge}</Badge>
              <CardTitle>{project.name}</CardTitle>
              <CardDesc>
                {project.desc.map((d, j) => <li key={j}>{d}</li>)}
              </CardDesc>
              <TechRow>
                {project.tech.map((t) => <TechPill key={t}>{t}</TechPill>)}
              </TechRow>
              {project.link && (
                <CardLink href={project.link} target="_blank" rel="noopener noreferrer">
                  View Project →
                </CardLink>
              )}
            </Card>
          </FadeIn>
        ))}
      </Grid>
    </ProjectsContainer>
  );
};

export default ProjectsSection;
